package com.procurement.vendorquotation.entity;import com.procurement.product.entity.Product;import com.procurement.rfq.entity.RfqLine;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity @Table(name="vendor_quotation_lines",uniqueConstraints=@UniqueConstraint(columnNames={"vendor_quotation_id","rfq_line_id"}))@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class VendorQuotationLine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="vendor_quotation_line_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_quotation_id",nullable=false)private VendorQuotation vendorQuotation;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="rfq_line_id",nullable=false)private RfqLine rfqLine;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Column(nullable=false,precision=15,scale=3)private BigDecimal quantity;@Column(name="unit_price",nullable=false,precision=15,scale=2)private BigDecimal unitPrice;@Column(name="discount_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal discountPercentage=BigDecimal.ZERO;@Column(name="tax_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal taxPercentage=BigDecimal.ZERO;@Column(name="line_amount",nullable=false,precision=15,scale=2)private BigDecimal lineAmount;@Column(length=500)private String remarks;}
